@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    BasicContentHandlerFactory that = (BasicContentHandlerFactory) o;
    return writeLimit == that.writeLimit && throwOnWriteLimitReached == that.throwOnWriteLimitReached && validateXHTML == that.validateXHTML && type == that.type;
}
